        question: "可以直接用MD5存储密码吗？",
        answer:
          "不建议。单纯的MD5或SHA哈希存储密码是不安全的，因为可以通过彩虹表（预计算的哈希对照表）快速破解。正确的做法是使用加盐（Salt）的哈希，或者使用专门的密码哈希算法如bcrypt、scrypt、Argon2等。这些算法计算速度慢，可以有效抵御暴力破解攻击。",
